// 测试用：模拟"改正则后聊天只剩开场白"的坏保存。只在测试聊天（分支）里用！
(async () => {
  const c = window.parent.SillyTavern.getContext();
  if (c.chat.length < 5) {
    toastr.error('请在至少 5 楼的测试聊天里运行');
    return;
  }
  const before = c.chat.length;
  const greeting = c.chat[0];
  c.chat.splice(0, c.chat.length, greeting); // 内存里只剩开场白
  await c.saveChat(); // 尝试把它存进文件
  toastr.info(`已模拟一次坏保存：${before} 楼 → 1 楼`);
})();
